def selectie_min_log(L):
    schimbari = []
    n = len(L)
    for i in range(n):
        minim = i
        for j in range(i+1, n):
            if L[j] < L[minim]:
                minim = j
        if minim != i:
            L[i], L[minim] = L[minim], L[i]
            schimbari.append(i)
    return L, schimbari

