def bubble(L):
    n = len(L)
    for i in range(n):
        for j in range(0, n - i - 1):
            if L[j] ___ L[j + 1]:   # interschimbă dacă sunt în ordine greșită
                L[j], L[j + 1] = L[j + 1], L[j]
    return L

def counting_sort(lista, max_val):
    freq = [0] * (max_val + 1)
    for x in lista:
        freq[x] += 1
    rez = []
    for val in range(max_val + 1):
        rez.extend([val] * freq[val])
    return rez

print(counting_sort([2, 3, 2, 1, 3], 3))

