def bubble_optimizat(L):
    n = len(L)
    for i in range(n):
        schimbat = False
        for j in range(0, n - i - 1):
            if L[j] > L[j+1]:
                L[j], L[j+1] = L[j+1], L[j]
                schimbat = True
        if not schimbat:
            break
    return L
